import { randomUUID } from "node:crypto";
import { mkdir, writeFile } from "node:fs/promises";
import { PDF } from "@libpdf/core";

// Trusted synthetic documents and ephemeral keys only; generated bytes never enter Git.
const fixture = { password: randomUUID(), encryptedPdf: "", overPageLimitPdf: "" };
for (const [name, count] of [
  ["encryptedPdf", 1],
  ["overPageLimitPdf", 101],
]) {
  const pdf = PDF.create();
  pdf.setTitle("Synthetic locked invoice 12,345 yen");
  for (let index = 0; index < count; index++) pdf.addPage();
  pdf.setProtection({ userPassword: fixture.password, ownerPassword: randomUUID() });
  // oxlint-disable-next-line no-await-in-loop -- Generate two bounded trusted fixtures once before tests.
  const bytes = await pdf.save({
    useXRefStream: true,
    compressStreams: true,
    compressionThreshold: 0,
  });
  fixture[name] = Buffer.from(bytes).toString("base64");
}
await mkdir(".cloudflare", { recursive: true });
await writeFile(".cloudflare/attachment-fixture.json", JSON.stringify(fixture));
